# Builds crates/torcdf-app/assets/THIRD_PARTY_LICENSES.txt from the hand-kept C-library part
# (c-libraries-licences.txt) and the Rust-crate part generated by cargo-about (about.toml / about.hbs).
# cargo-about fails on any licence not accepted in about.toml (GPL-3.0-compatible only).
#
#   installer\licences.ps1          regenerate the file
#   installer\licences.ps1 -Check   exit 1 if the committed file is out of date
param([switch]$Check)
$ErrorActionPreference = 'Stop'

$root = Split-Path -Parent $PSScriptRoot
$assets = Join-Path $root 'crates\torcdf-app\assets'
$target = Join-Path $assets 'THIRD_PARTY_LICENSES.txt'
$tmp = Join-Path ([IO.Path]::GetTempPath()) ("torcdf-crates-" + [guid]::NewGuid() + '.txt')

Push-Location $root
try {
    & cargo about generate -m crates/torcdf-app/Cargo.toml about.hbs -o $tmp
    if ($LASTEXITCODE -ne 0) { Write-Error "cargo about failed (exit $LASTEXITCODE): a licence is not accepted or a crate could not be resolved" }
} finally { Pop-Location }

function Read-Normalised([string]$path) {
    ([IO.File]::ReadAllText($path)) -replace "`r`n", "`n"
}

$cpart = Read-Normalised (Join-Path $assets 'c-libraries-licences.txt')
$crates = Read-Normalised $tmp
Remove-Item $tmp
$text = $cpart.TrimEnd("`n") + "`n`n" + $crates.TrimEnd("`n") + "`n"

if ($Check) {
    $current = if (Test-Path $target) { Read-Normalised $target } else { '' }
    if ($current -ne $text) {
        Write-Host "THIRD_PARTY_LICENSES.txt is out of date: run installer\licences.ps1 and commit the result."
        exit 1
    }
    Write-Host "THIRD_PARTY_LICENSES.txt is up to date."
    exit 0
}

[IO.File]::WriteAllText($target, $text, (New-Object Text.UTF8Encoding($false)))
Write-Host "Wrote $target"
